import java.util.*;
public class Main {
    static List<String> validateCreate(Map<String,String> m){
        List<String> e=new ArrayList<>();
        if(!m.containsKey("username")||m.get("username").isEmpty()) e.add("create: username required");
        if(!m.containsKey("password")||m.get("password").length()<6) e.add("create: password min 6");
        return e;
    }
    static List<String> validateUpdate(Map<String,String> m){
        List<String> e=new ArrayList<>();
        if(!m.containsKey("id")||m.get("id").isEmpty()) e.add("update: id required");
        return e;
    }
    public static void main(String[] a){
        Map<String,String> create=new LinkedHashMap<>();
        create.put("username","bob"); create.put("password","123");
        Map<String,String> update=new LinkedHashMap<>();
        update.put("username","bob");
        System.out.println("create violations: "+validateCreate(create));
        System.out.println("update violations: "+validateUpdate(update));
    }
}
